import{_ as s,l,o as e,c as i,v as t,p,x as r,d as n,i as d,S as P}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"P4 可编程","description":"","frontmatter":{"title":"P4 可编程","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/p4-programmable.md","filePath":"cs/p4-programmable.md","lastUpdated":1789023840000}'),c={name:"cs/p4-programmable.md"};function h(m,a,A,u,_,C){const o=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="p4-可编程" tabindex="-1">P4 可编程 <a class="header-anchor" href="#p4-可编程" aria-label="Permalink to &quot;P4 可编程&quot;">​</a></h1><div class="epigraph"><p>P4 描述解析器与匹配-动作流水线，编译到 ASIC 或 CPU；协议头不再焊死在硅里，但仍受阶段数与 TCAM 形状约束。</p><footer>—— 据 Bosshart et al., P4, ACM SIGCOMM CCR 2014；P4<sub>16</sub> 语言规范整理</footer></div><p><a href="/cs/sdn-openflow">上一课</a> 的匹配域是固定的。新隧道头要等芯片代次。缺口是<strong>可编程数据面</strong>：P4 写 parse → match-action → deparse。本课不把 Clos 拓扑写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>OpenFlow 加字段靠规范版本。P4：声明头、解析图、表、动作，目标无关再映射到 Tofino 或智能网卡。仍不是通用 CPU：无任意循环、表宽与阶段固定。INT 带内遥测、自定义熵、新封装可在此做。控制面仍要某协议装表——P4 不替代 BGP，只替换「转发 ASIC 焊死」那一层。</p><p>不要把 P4 写成智能合约或机器学习训练。</p><p><span class="marginnote">P4<sub>16</sub>。PSA/PNA 架构。本课不写完整编译器。</span></p><h3 id="不是通用-cpu" tabindex="-1">不是通用 CPU <a class="header-anchor" href="#不是通用-cpu" aria-label="Permalink to &quot;不是通用 CPU&quot;">​</a></h3><p>解析与表可描述，阶段数与表宽仍硬。不取消 BGP，只放开头格式。错误程序可成黑洞。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：解析图 → 多级表 → 出端口。对照 TCAM：表仍可能编译成 TCAM/SRAM。与线路码对照：都是「可描述的转发」，一层在 PHY，一层在 L2–L4。</p>',11)),(e(),p(P,null,{default:r(()=>[d(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PAR%5B%22%E5%8F%AF%E7%BC%96%E7%A8%8B%E8%A7%A3%E6%9E%90%22%5D%20--%3E%20MA%5B%22%E5%8C%B9%E9%85%8D-%E5%8A%A8%E4%BD%9C%E9%98%B6%E6%AE%B5%22%5D%0A%20%20MA%20--%3E%20DEP%5B%22%E9%87%8D%E7%BB%84%22%5D%0A%20%20CTL%5B%22%E6%8E%A7%E5%88%B6%E9%9D%A2%22%5D%20--%3E%20MA%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>VXLAN/SR 新 SID 可用 P4 先部署再等标准芯片。错误程序可把交换机变成黑洞，需要测试与资源上限。C10K 后课是主机端；这里是网络端可编程。容量 \\(C\\) 仍由端口 PHY 决定，P4 只动如何选口。</p><p>与 HOL：流水线阶段加深可能加纳秒，不解决输出热点。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 eBPF 与 P4 的全部对照。数据中心 Clos 是下一课。后课默认：数据面可编程受流水线资源约束，不是通用计算。</p><p>把全部政策塞进 P4 会让控制面版本与芯片资源强耦合。</p><p>上一课留下的缺口在本课收口；「P4 可编程」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/datacenter-clos">数据中心 Clos / 胖树</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>P4 定义解析与表，编译到受限硬件。</li><li>不取消控制面协议，只放开头格式。</li><li>资源阶段数是硬边界。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Bosshart et al., 2014；P4<sub>16</sub>。</li></ul>',10))])}const f=s(c,[["render",h]]);export{b as __pageData,f as default};
